insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Chrome parts rust in monsoon','Riders in coastal and Malnad areas report rust spots on chrome and spokes after the rainy season.','low','Wash after rain, apply anti-rust spray or wax every few weeks.' from public.bikes where slug = 're-classic-350';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Rear brake squeal','Squeaking from the rear brake, especially in wet conditions.','low','Clean the brake assembly and check pad wear at the next service.' from public.bikes where slug = 're-classic-350';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Heavy in slow traffic','At 195 kg it is tiring in stop-and-go Bengaluru traffic, and the clutch can feel heavy.','medium','Keep the clutch cable lubricated and adjusted. A service centre can check free play.' from public.bikes where slug = 're-classic-350';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Stiff rear suspension','Bumpy ride over potholes and speed breakers, especially when riding solo.','medium','Adjust rear preload to the softest setting. Check tyre pressure is not too high.' from public.bikes where slug = 're-hunter-350';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Engine heat in traffic','Heat felt on the legs during long traffic jams.','low','Normal for air-oil cooled engines. Make sure the oil level is correct.' from public.bikes where slug = 're-hunter-350';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Engine heating in traffic','The radiator fan runs often and riders feel heat in slow city traffic.','medium','Check coolant level regularly and clean the radiator fins.' from public.bikes where slug = 'bajaj-pulsar-ns200';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Chain slack and noise','Chain loosens quickly and becomes noisy if not maintained.','low','Clean and lube every 500 to 700 km, adjust slack every service.' from public.bikes where slug = 'bajaj-pulsar-ns200';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Rear tyre grip in the wet','Some owners feel the stock rear tyre slides on wet roads.','medium','Ride gently in rain. Upgrade to a same-size tyre with better wet grip.' from public.bikes where slug = 'bajaj-pulsar-ns200';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Vibrations at high RPM','Buzz felt in footpegs and handlebar above 8,000 RPM.','low','Upshift earlier for cruising. Check engine mounting bolts at service.' from public.bikes where slug = 'tvs-apache-rtr-160-4v';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Battery drain when parked long','Battery goes flat if the bike is unused for 2 to 3 weeks.','medium','Start and ride the bike weekly or use a trickle charger.' from public.bikes where slug = 'tvs-apache-rtr-160-4v';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Firm rear suspension','Feels harsh on broken roads with a pillion.','low','Adjust preload and keep tyre pressure to the manual''s value.' from public.bikes where slug = 'tvs-raider-125';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Chain noise','Chain becomes noisy quickly in dusty conditions.','low','Clean and lube the chain regularly.' from public.bikes where slug = 'tvs-raider-125';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Weak drum brakes','Braking feels weak, especially with a pillion or on downhill roads.','medium','Adjust the brake rods and replace worn shoes. Ride with more distance.' from public.bikes where slug = 'hero-splendor-plus';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Rough idling','Engine idles unevenly or stalls when cold.','low','Get the air filter and spark plug checked. Warm up for 30 seconds.' from public.bikes where slug = 'hero-splendor-plus';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Rust on silencer','Silencer and footrest brackets show rust after a few years.','low','Use heat-resistant paint or anti-rust coating on the silencer.' from public.bikes where slug = 'honda-shine-125';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Soft front suspension','Front dives a lot under hard braking.','low','Change fork oil at the interval in the manual.' from public.bikes where slug = 'honda-shine-125';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Wrist and back strain','Sporty riding position is tiring for daily commutes.','medium','Take breaks on long rides. Strengthen your core, do not lean on your wrists.' from public.bikes where slug = 'yamaha-r15-v4';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Small mirrors','Limited rear view, mostly elbows visible.','low','Adjust mirrors outward. Any replacement must keep a clear rear view.' from public.bikes where slug = 'yamaha-r15-v4';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Hard seat on long rides','Seat becomes uncomfortable after an hour.','low','Use a seat cover with gel padding or take short breaks.' from public.bikes where slug = 'yamaha-mt-15';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Engine heat in traffic','Heat felt on the right leg in jams.','low','Check coolant level and fan operation at every service.' from public.bikes where slug = 'yamaha-mt-15';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Engine heat in city traffic','Very hot in slow traffic, the fan runs constantly.','high','Keep coolant topped up, avoid long idling, switch off at long signals.' from public.bikes where slug = 'ktm-390-duke';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Higher service cost','Parts and service are more expensive than commuter bikes.','medium','Follow the service schedule strictly to avoid bigger repair bills.' from public.bikes where slug = 'ktm-390-duke';
insert into public.issues (bike_id,title,description,severity,fix_tip) select id, 'Electrical glitches','Some owners report display or sensor warning lights appearing randomly.','medium','Get it scanned at an authorised KTM service centre. Often covered by warranty.' from public.bikes where slug = 'ktm-390-duke';
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('aftermarket-exhaust','Clip-on / slip-on exhaust','wind','Replaces the stock silencer with a louder, freer-flowing aftermarket one.',2,6,-12,-5,8,15,'Louder sound, slightly lighter. Without a remap the engine may run lean and pop on deceleration.','illegal','Not allowed on public roads anywhere in India. Changing the silencer alters the bike from its approved specification, and loud silencers break noise rules.','MV Act 1988 Sec. 52 (alteration), Sec. 190(2) (noise / pollution), Sec. 182A(4) (penalty), CMVR Rule 120 (silencer)','https://www.thequint.com/amp/story/news/india/bengaluru-traffic-police-modified-silencers-royal-enfield') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('performance-air-filter','Performance air filter','fan','Drop-in reusable filter that lets the engine breathe more easily.',1,3,-2,1,0,1,'Washable and reusable. Poor quality filters can let dust into the engine.','conditional','A drop-in filter that fits the original airbox is a replacement part, not a structural change. Open pod filters that remove the airbox, or anything that raises emissions, are not allowed.','MV Act 1988 Sec. 52 (replacement parts with equivalent performance), emission norms (BS6)','https://thewire.in/law/why-you-should-think-twice-before-modifying-your-car') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('ecu-remap','ECU remap / fuel controller','cpu','Reprograms the engine computer for more aggressive fuel and ignition maps.',5,10,-10,-5,0,2,'Sharper throttle. Usually voids warranty and can increase engine heat.','illegal','Changes engine performance and emissions away from the type-approved specification. Not allowed on public roads, and insurers may reject claims for undeclared changes.','MV Act 1988 Sec. 52, Sec. 182A(4), BS6 emission norms','https://newskarnataka.com/bengaluru/bengaluru-student-fined-%e2%82%b91-11-lakh-for-illegal-car-silencer-modification/15012026/') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('sprocket-change','Sprocket change','settings','Smaller front or bigger rear sprocket for quicker acceleration.',0,0,-8,-3,0,0,'Faster pickup, lower top speed, higher RPM on highways. Speedometer may read wrong.','conditional','Not listed on the RC, so often tolerated, but it changes the bike from manufacturer specification. Safest to stick to manufacturer-approved sizes.','MV Act 1988 Sec. 52','https://www.casemine.com/in/column/section-52-of-the-motor-vehicles-act,-1988:-judicial-interpretation-and-regulatory-challenges/view') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('led-headlight','LED headlight bulb','lightbulb','Brighter white LED bulb in place of the stock halogen.',0,0,0,0,0,0,'Better night visibility, less load on the battery. Bad bulbs can blind oncoming traffic.','conditional','OK if it fits the original headlight housing and keeps a proper beam pattern (white or yellow, no glare). Coloured, flashing or extra-bright aux lights are not allowed.','CMVR 1989 lighting rules, MV Act 1988 Sec. 52','https://www.ridenrepair.com/blog-details/top-10-bike-modifications-legal-india-2026') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('wider-tyres','Wider tyres','circle-dot','Fatter rear or front tyre for looks and grip.',-1,0,-5,-2,0,0,'Better looks and dry grip, slower steering. Same-size premium tyres give grip without the downsides.','conditional','Same size as the manufacturer spec is legal. A different (wider) size is an alteration. The Supreme Court has said Sec. 52 even covers changing to higher-capacity tyres.','MV Act 1988 Sec. 52, Supreme Court: RTO v. K. Jayachandra (2019)','https://www.scconline.com/blog/?p=207891') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_parts (slug,name,icon,description,power_pct_min,power_pct_max,mileage_pct_min,mileage_pct_max,noise_db_min,noise_db_max,other_effects,legal_status,legal_summary,law_refs,source_url) values ('pressure-horn','Loud / pressure horn','volume-2','Air or multi-tone horn louder than the stock one.',0,0,0,0,10,20,'Very loud. Can drain the battery and disturb residents.','illegal','Multi-tone and pressure horns are not allowed. Traffic police regularly fine and remove them.','CMVR 1989 Rule 119 (horns), MV Act 1988 Sec. 190(2)','https://ts.yourstory.com/2017/12/bengaluru-police-royal-enfield-exhaust') on conflict (slug) do update set name=excluded.name, icon=excluded.icon, description=excluded.description, power_pct_min=excluded.power_pct_min, power_pct_max=excluded.power_pct_max, mileage_pct_min=excluded.mileage_pct_min, mileage_pct_max=excluded.mileage_pct_max, noise_db_min=excluded.noise_db_min, noise_db_max=excluded.noise_db_max, other_effects=excluded.other_effects, legal_status=excluded.legal_status, legal_summary=excluded.legal_summary, law_refs=excluded.law_refs, source_url=excluded.source_url, last_checked=current_date;
insert into public.mod_state_notes (part_id,state_slug,note,source_url) select id, 'karnataka', 'Bengaluru traffic police seize these and fine riders.', 'https://www.thequint.com/amp/story/news/india/bengaluru-traffic-police-modified-silencers-royal-enfield' from public.mod_parts where slug = 'aftermarket-exhaust';
